import React from "react";

const Footer = () => {
  return (
    <footer className="bg-blue-950 text-gray-300 py-6 text-center">
      <div className="max-w-6xl mx-auto px-6">
        <h2 className="text-lg font-semibold text-blue-200 mb-2">
          Contact Us
        </h2>
        <p>Email: support@aiinterviewcoach.com</p>
        <p>Phone: +91 98765 43210</p>
        <p>Address: 123 AI Street, Bengaluru, India</p>
        <hr className="border-blue-800 my-4" />
        <p className="text-sm text-gray-400">
          © {new Date().getFullYear()} AI Interview Coach. All rights reserved.
        </p>
      </div>
    </footer>
  );
};

export default Footer;
